		"realm",
		"startTime",
		"endTime",
		"raidUid",
		"raidNid",
		"status",
		"authorityEpoch",
		"sequence",
		"digest",
		"checkpointSequence",
		"events",
		"players",
		"bossKills",
		"attendance",
		"loot",
		"nextPlayerNid",
		"nextBossNid",
		"nextLootNid",
		"unknownField",
	}
	for i = 1, #protectedKeys do
		local state = {
			zone = "ICC",
			players = {},
			bossKills = {},
			attendance = {},
			loot = {},
			nextPlayerNid = 3,
