		return nil
	end
	_G.SendAddonMessage = function() end
	_G.RegisterAddonMessagePrefix = function() end
	_G.strsplit = function(_, value)
		local a, b = string.match(value, "^([^-]+)%-?(.*)$")
		return a, b ~= "" and b or nil
	end
	_G.wipe = function(t)
		for key in pairs(t) do
			t[key] = nil
		end
		return t
	end
