	end
	fixture.windowItemCount = 20
	assertTrue(fixture.awardSequence:Start("item:19019", 20, winners), "bounded sequence must start")
	for i = 1, 20 do
		assertEqual(
			true,
			fixture.master._awardConfirmation:Confirm(1),
			"bounded confirmation failed at " .. tostring(i)
		)
